CREATE TABLE IF NOT EXISTS player_game_state(player_id TEXT PRIMARY KEY REFERENCES players(player_id) ON DELETE CASCADE,quacks INTEGER NOT NULL DEFAULT 0 CHECK(quacks>=0),lifetime_quacks INTEGER NOT NULL DEFAULT 0 CHECK(lifetime_quacks>=0),rebirths INTEGER NOT NULL DEFAULT 0 CHECK(rebirths>=0),upgrades_json TEXT NOT NULL DEFAULT '{}',last_accrual INTEGER NOT NULL,updated_at INTEGER NOT NULL);
